begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text);
grant all on tap_results to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('50000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(n),'role','authenticated','session_id',pg_temp.i(n),'is_anonymous',false)::text,true)$$;
create temporary table report_snapshots(name text primary key,data jsonb);
grant all on report_snapshots to authenticated;
create function pg_temp.ctx(b integer default 101) returns jsonb language sql as $$select jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(b))$$;
create function pg_temp.report(extra jsonb default '{}') returns jsonb language sql as $$select public.agri_command('stock_loss_report',pg_temp.ctx()||extra)$$;
create function pg_temp.cost(key text,ident integer,amount text default '125000',previous integer default null) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('lossKey',key,'costEvidenceId',pg_temp.i(ident),'expectedCostId',case when previous is null then null else pg_temp.i(previous) end,'unitId',pg_temp.i(401),'unitCostCentavos',amount,'zeroCostConfirmed',false,'reference','TEST supplier invoice 021','reason','TEST verified cost for one 50 kg sack')$$;
create function pg_temp.loss_key(source integer) returns text language sql as $$select 'movement:'||id from public.inventory_movements where source_id=pg_temp.i(source) and kind in ('loss','adjustment')$$;
set local role authenticated;
select pg_temp.login(11);
select public.agri_command('approve_stock_issue',pg_temp.ctx()||jsonb_build_object('issueId',pg_temp.i(801),'reason','TEST checked physical quantity'));
select public.agri_command('record_stock_issue',pg_temp.ctx()||jsonb_build_object('issueId',pg_temp.i(802),'productId',pg_temp.i(301),'quantity','2','category','damage','disposition','hold','reason','TEST damaged goods held'));
select public.agri_command('approve_stock_issue',pg_temp.ctx()||jsonb_build_object('issueId',pg_temp.i(802),'reason','TEST held separately'));
select public.agri_command('disposition_hold',pg_temp.ctx()||jsonb_build_object('holdId',(select id from public.stock_holds where source_id=pg_temp.i(802)),'dispositionId',pg_temp.i(803),'quantity','1','disposition','dispose','reason','TEST one damaged kilo disposed'));
select public.agri_command('dispatch_transfer',pg_temp.ctx()||jsonb_build_object('transferId',pg_temp.i(804),'productId',pg_temp.i(301),'quantity','10','destinationBranchId',pg_temp.i(102)));
select public.agri_command('receive_transfer',pg_temp.ctx(102)||jsonb_build_object('transferId',pg_temp.i(804),'receiptId',pg_temp.i(805),'quantity','8','heldQuantity','0','reason','TEST two kilos missing at receipt'));
select public.agri_command('write_off_transfer',pg_temp.ctx(102)||jsonb_build_object('transferId',pg_temp.i(804),'receiptId',pg_temp.i(806),'quantity','2','reason','TEST owner verified two kilo shortage'));
select public.agri_command('record_loss_cost',pg_temp.cost('held:'||pg_temp.i(803),951,'150000'));
select public.agri_command('record_loss_cost',pg_temp.cost('transfer:'||pg_temp.i(806),952));
select public.agri_command('record_stock_issue',pg_temp.ctx()||jsonb_build_object('issueId',pg_temp.i(807),'productId',pg_temp.i(301),'quantity','1','category','owner_use','disposition','write_off','reason','TEST authorised business use'));
select public.agri_command('approve_stock_issue',pg_temp.ctx()||jsonb_build_object('issueId',pg_temp.i(807),'reason','TEST owner approved use'));
reset role;
set local role authenticated;
select pg_temp.login(11);
select pg_temp.login(12);
select pg_temp.login(13);
select pg_temp.login(14);
select pg_temp.login(15);
select pg_temp.login(11);
reset role;
set local role authenticated;
select pg_temp.login(11);
do $$declare previous integer:=940; n integer; begin for n in 1..51 loop perform public.agri_command('record_loss_cost',pg_temp.cost(pg_temp.loss_key(801),16000+n,'130000',previous));previous:=16000+n;end loop;end$$;
reset role;
select line from tap_results;
rollback;
